/**
 * Dev-only fixtures that stand in for a real FedEx read until discovery wires it (step-8 phase 1).
 *
 * These are MADE UP. Nobody here has seen a real VIPS open-time or View/Add list. The fixture text is generated by the
 * same `samplePaste` the pages already offer as "Try a made-up list", so the live path and the paste path read
 * identical input and therefore produce identical results — which is exactly what we need to prove the wiring before
 * any real feed exists. Both screens read the same kind of list, so both fixtures come from the same generator: one
 * scanner, one fixture shape.
 */

import { samplePaste } from "@/lib/open-time/sample";
import type { BidPack } from "@/types/bidpack";

/** A fixture open-time list for this pack, for exercising the live feed on fixtures. Not a real VIPS list. */
export function fixtureOpenTimeText(pack: BidPack): string {
  return samplePaste(pack);
}

/**
 * A fixture View/Add make-up list for this pack. Same list format as open time (that's the point — one scanner), so it
 * reuses the same generator. Not a real VIPS View/Add page: a current pilot still has to save one real copy first.
 */
export function fixtureViewAddText(pack: BidPack): string {
  return samplePaste(pack);
}
